SELECT pac.Id,pac.ProductId,pac.Sku,pac.StockQuantity,pac.StockAvailabilityTypeId,pac.ManageInventoryMethodId,pac.FinalPrice,pac.OverriddenPrice,pac.OverriddenPriceTorob,pac.OldPrice,pac.OldPriceStartDateUtc,pac.OldPriceEndDateUtc,pac.SupplierProductAttributeCombinationId,pac.PictureId,pac.ColorProductInventoryAttributeValueId,pac.GuaranteeProductInventoryAttributeValueId,pac.WeightProductInventoryAttributeValueId FROM ProductAttributeCombination pac JOIN Product p ON p.Id=pac.ProductId WHERE p.Published=1 AND p.Deleted=0 AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0
